"""LT discovery configuration from cms/envs/aws.py; no environment secrets."""

def configure(namespace):
    values = dict(namespace)
    exec("LANGUAGE_MAP = {'terms': {lang: display for lang, display in ALL_LANGUAGES}, 'name': 'Language'}\nPROGRAM_DISCOVERY_FILTERS = ['languages', 'visibility']\nCOURSE_DISCOVERY_FILTERS = ['course_category', 'course_type', 'languages', 'privilege_ids', 'catalog_visibility']\nCOURSE_DISCOVERY_FACETS = {'privilege_ids': {'size': 1000}, 'course_category': {'size': 100}, 'course_type': {'size': 100}, 'languages': {'size': 100}, 'catalog_visibility': {'size': 100}}\nCOURSE_DISCOVERY_MEANINGS = {'languages': LANGUAGE_MAP, 'status': {'name': 'Status', 'terms': {'past': 'Archived', 'current': 'Published', 'future': 'Draft'}}, 'course_type': {'name': 'Type', 'terms': dict(COURSE_TYPES)}, 'course_category': {'name': 'Category'}, 'vendor': {'name': 'Tag'}, 'course_mandatory_enabled': {'name': 'Mandatory', 'terms': dict(MANDATORY_OPTIONS)}, 'course_country': {'name': 'Country'}, 'enrollment_learning_groups': {'name': 'Learning Group'}, 'privilege_ids': {'name': 'Course Privilege Flag', 'terms': {}}, 'catalog_visibility': {'name': 'Visibility', 'terms': dict(COURSE_VISIBILITY)}}", values)
    namespace.update({name: values[name] for name in ['COURSE_DISCOVERY_FACETS', 'COURSE_DISCOVERY_FILTERS', 'COURSE_DISCOVERY_MEANINGS', 'LANGUAGE_MAP', 'PROGRAM_DISCOVERY_FILTERS']})
